using System.Text.Json.Nodes;
namespace NanoCAD.McpServer;
internal static class ModelSketchSchema
{
    private static JsonObject Num(double a=-1e6,double b=1e6)=>new(){["type"]="number",["minimum"]=a,["maximum"]=b};
    private static JsonObject Point()=>new(){["type"]="array",["minItems"]=3,["maxItems"]=3,["items"]=Num()};
    private static JsonObject Id()=>new(){["type"]="string",["pattern"]="^\\{[0-9A-Fa-f]{8}-[0-9A-Fa-f]{4}-[0-9A-Fa-f]{4}-[0-9A-Fa-f]{4}-[0-9A-Fa-f]{12}\\}$"};
    private static JsonObject Obj(JsonObject properties)=>new(){["type"]="object",["additionalProperties"]=false,["properties"]=properties,["required"]=new JsonArray(properties.Select(p=>(JsonNode?)JsonValue.Create(p.Key)).ToArray())};
    private static JsonObject Geometry()=>new(){["oneOf"]=new JsonArray(
        Obj(new(){["kind"]=new JsonObject{["const"]="line"},["start"]=Point(),["end"]=Point()}),
        Obj(new(){["kind"]=new JsonObject{["const"]="circular_arc"},["center"]=Point(),["radius"]=Num(.001),["normal"]=Point(),["reference_direction"]=Point(),["start_angle"]=Num(),["end_angle"]=Num(),["angle_unit"]=new JsonObject{["const"]="radians"}}))};
    internal static JsonObject Operation()
    {
        var o=Obj(new(){["operation"]=new JsonObject{["const"]="set_model_sketch_geometry"},["handles"]=new JsonObject{["type"]="array",["minItems"]=1,["maxItems"]=1,["items"]=new JsonObject{["type"]="string",["pattern"]="^[0-9A-Fa-f]{1,16}$"}},
            ["expected_last_item_id"]=Id(),["sketch_id"]=Id(),["elements"]=new JsonObject{["type"]="array",["minItems"]=1,["items"]=Obj(new(){["element_id"]=Id(),["expected_geometry"]=Geometry(),["geometry"]=Geometry()})}});
        o["description"]="Edit existing Line/CircularArc elements in one native model sketch without adding/deleting elements. First inspect_model_history with sketch_geometry_ids; use its WCS geometry, element IDs and current last_item_id. Supply expected_geometry and replacement geometry, same kind, for the selected existing elements together; include all endpoint changes needed to keep the full contour closed/simple. Arc frame is center, perpendicular unit normal/reference_direction and start/end radians (a full circle spans2*pi). Plane stays fixed. Retained profiles can rebuild known native extrusion/revolution/sweep/loft consumers together with hole/thread/shell/fillet/chamfer/pattern/mirror, placement and WorkPlane/WorkPoint/WorkAxis history. Each profile must retain its owning sketch/body, all known consumers and driver expressions. Unsupported history types remain protected. The simpler straight-extrusion route currently requires one additive base followed by explicitly ordered one-to-one cut/join extrusions, including a projected base when editing an internal tail sketch. For one body, put edits of distinct retained sketches in one modify_entities request. The simpler straight-extrusion route allows connected edits of distinct sketches in one request to change the base and dependent cut/join profiles together; all selected geometry rebuilds once before commit. In that simpler route, healthy native fillet/chamfer, inward shell or rectangular-pattern features may occur in the ordered history. Their parameters, ownership and order must survive the rebuild; inspect opening/edge intent, repeated elements and resulting shape after editing. Supported model edits may be followed by healthy native associative drawing views forming a terminal history chain; their links, settings and nonempty updated geometry are checked. Healthy section views with one retained source and an addressable non-live section definition are included; broken views remain outside this route. Use retained source projections (created with editable_profile=true); anonymous old sketches remain protected. Shared projection/axis/path sources and sources consumed by another model body are protected. Sources with associative drawing constraints/dependencies require their dimension-driven route. Requires proven writable source DbGeometry matching WCS; no delete/recreate fallback. Checks actual edited contours, sketch IDs, other profiles, feature identities/order, variables/expressions and body health. This direct shape edit does not create/solve MCS constraints or change depth parameters. ROLLBACK_NOT_GUARANTEED: a started failure has unknown outcome and requires inspection of this model; no automatic Undo. Use returned body_ref if native rebuild replaced its DWG representation. Refresh topology, history and views, then visually check the changed feature group.";
        return o;
    }
}

